    BRD = { middles = Character.Persona.Playful, openers = Character.PersonaOpeners.Playful, closers = Character.PersonaClosers.Playful },
    WAR = {
        middles = {
            engage = { 'That {mob} picked a fight with an axe.', 'Time to introduce {mob} to my great axe.', 'I do not charge in. I arrive loudly.', 'Berserk is on. Manners are off.', 'My axe is hungry and {mob} is dinner.', 'Let us see how tough {mob} really is.', 'I tank with my face. It works fine.', 'Provoke first. Apologize never.', '{mob} looks smashable. Let us test that.', 'I brought an axe to a staring contest.', 'Charge now. Think later. Maybe never.', 'My plan is simple. Hit it harder.', '{mob} chose violence. Excellent choice.', 'I am the wall. {mob} is the crash test.', 'Great axe out. Subtlety stays home.', 'Let us turn {mob} into a cautionary tale.', 'I do not dodge. I absorb with style.', '{mob} is about to meet the floor.', 'Smash first. Ask questions never.', 'My muscles have muscles. {mob} is doomed.', 'I am here to hit things and look great.', '{mob} picked the wrong wall of muscle.', 'Berserk mode engaged. Brain mode optional.', 'I charge headfirst. It has never failed me.', 'That {mob} is going down in pieces.', 'My axe solves problems. {mob} is a problem.', 'I am not reckless. I am enthusiastically brave.', '{mob} meet axe. Axe meet {mob}. Fun times.', 'I will hit it until it stops moving.', 'Tanking is just hugging with an axe.', '{mob} is toast. I am the toaster.', 'I do not run from fights. I run at them.', 'Let us make {mob} regret existing.', 'My war cry is mostly just yelling.', '{mob} is in for a very bad day.', 'I swing big. I miss big. I hit bigger.', 'Headfirst is a valid strategy. Watch this.', '{mob} has no idea what is coming.', 'I am the storm with an axe attached.', 'Time to smash {mob} back to the stone age.' },
            idle = { 'Fight over. My axe needs a breather too.', 'Resting now. Even walls need a break.', 'I smashed it. I am allowed to sit now.', 'That was a workout. Where is my snack.', 'Idle time is just flexing time.', 'My axe is heavy. My ego is heavier.', 'I earned this rest. I hit things hard.', 'Sitting down is also a warrior skill.', 'The dust settles. I am still standing.', 'I could fight all day. I choose not to.', 'Rest now. Smash later. Simple schedule.', 'My muscles are cooling down. Very slowly.', 'That fight was barely a warmup.', 'I am resting my axe and my awesome.', 'Victory tastes like sweat and glory.', 'I stand guard. I also stand around.', 'Time to catch my breath and look tough.', 'I did the smashing. Now I do the sitting.', 'Even great warriors need a water break.', 'I am not lazy. I am recharging for smashing.', 'The ground is my chair. I earned it.', 'I will rest until the next thing to hit.', 'My axe and I are taking a victory lap.', 'That was fun. Let us do it again soon.', 'I am calm now. The axe is less calm.', 'Resting is part of the smash plan.', 'I look great even when doing nothing.', 'My heart rate is back to heroic.', 'I survived. Again. Shocking, I know.', 'Time to polish the axe and the legend.', 'I am a wall on break. Do not disturb.', 'That fight is done. Next victim, please.', 'I am conserving energy for more smashing.', 'Sitting is just standing with style.', 'My war cry needs a quick nap too.', 'I fought hard. Now I nap hard.', 'The quiet after a fight feels pretty great.', 'I am ready for the next round. Almost.', 'Resting now. My axe is still ready.', 'I am a hero at rest. Still heroic.' },
            low = { 'HP low. My axe is still very confident.', 'Half health. Full attitude. Still swinging.', 'I am bleeding a little. Mostly awesome though.', 'Low HP just means the fight got interesting.', 'My health is low. My stubbornness is high.', 'I have been hit. I am still here. Rude.', 'Half HP is plenty for a warrior like me.', 'I am hurt. I am also extremely annoyed.', 'My face tanked that. My face is fine.', 'Low health. High courage. Zero retreat.', 'I am at half power. Still twice the trouble.', 'That hurt. I will return the favor harder.', 'HP dropping. My grin is not dropping.', 'I am bruised. I am not beaten. Not even close.', 'Half health means half the worry. None.', 'I took a hit. I plan to take many more.', 'My HP is low. My axe is still hungry.', 'Being low just makes me swing angrier.', 'I am hurt but I am still the wall.', 'Low HP. High smash energy. Let us go.', 'I am dented. I am not done. Far from it.', 'My health bar is short. My temper is long.', 'I am at half. The enemy is at all trouble.', 'That was a solid hit. My turn now.', 'I am low on HP. Not low on confidence.', 'Bruised and dented, still standing tall.', 'My HP is dropping. So is their luck.', 'I feel pain. I also feel very motivated.', 'Half health is my favorite comeback zone.', 'I am wounded. I am also very unimpressed.', 'Low HP means I hit back even harder.', 'My armor is dented. My pride is not.', 'I am hurting. The enemy will hurt more.', 'Half HP. Double the shouting. Triple the smashing.', 'I am still up. That is what matters.', 'My HP is low. My axe disagrees with fear.', 'I took damage. I will collect payment in smashes.', 'Low health is just a dramatic pause.', 'I am not falling. I am leaning into it.', 'Half HP and still the toughest thing here.' },
