            engage = { 'That {mob} picked a fight with a healer. Bold.', 'I brought Cure and holy light. Guess which hurts.', 'You want a fight? I have a staff and opinions.', 'Healing is my day job. Smiting is my hobby.', 'That {mob} looks sick. I can fix that. Permanently.', 'I am the reason nobody dies here. Watch and learn.', 'Holy light, ready. Manners, optional. Let us go.', 'That {mob} just volunteered for a miracle. Poor thing.', 'My Cure hits harder than your sword. Probably.', 'I patch people up. I also patch {mob} down.', 'Time to show {mob} what holy really means.', 'I did not come to fight. I came to win. Same thing.', 'That {mob} has no idea what it just started.', 'Regen is up. Morale is up. Let us do this.', 'I heal allies and hurt enemies. Efficient, right?', 'That {mob} needs an appointment. With my staff.', 'Protect is on. Shell is on. Excuses are off.', 'I am a White Mage. I fix problems. With light.', 'That {mob} chose violence. I chose holy magic.', 'My staff is not a walking stick. Ask that {mob}.', 'I keep everyone alive. It is a tough job. Fun though.', 'That {mob} looks like it needs some divine attention.', 'Cure ready. Holy ready. Confidence ready. Go.', 'I am the last one standing. I am also the first to swing.', 'That {mob} will learn why healers are scary.', 'No dying on my watch. Dying on theirs is fine.', 'I brought bandages and a bad attitude. Let us go.', 'That {mob} is about to meet my holy side.', 'Healing hands, holy heart, zero patience for {mob}.', 'I do not miss. Light always finds its target.', 'That {mob} picked the wrong party to bother.', 'My job is keeping you alive. My hobby is smiting {mob}.', 'Let us make this quick. I have Cures to cast.', 'That {mob} is sick. Diagnosis: holy light deficiency.', 'I am calm, I am kind, and I am about to smite {mob}.', 'Protect up, Shell up, spirits up. Time to shine.', 'That {mob} wants trouble. Trouble is my middle name.', 'I heal fast and hit holy. Best of both worlds.', 'That {mob} just made my to-do list. Top priority.', 'Holy light incoming. Someone tell that {mob} to duck.' },
            idle = { 'Fight over. Everyone alive. You are welcome.', 'Another win. My Cure did most of the work.', 'Rest time. My staff needs a break too.', 'Everyone patched up. I am basically a miracle worker.', 'That fight was easy. My healing made it look easy.', 'All healed, all good. Who wants a snack?', 'I kept everyone alive again. No big deal. Okay, big deal.', 'Peace at last. My holy light can take a nap.', 'Another {mob} down. Another perfect record kept.', 'I call that a flawless victory. Mostly flawless.', 'Resting now. Even healers need a breather.', 'Nobody died. I am putting that on my resume.', 'That was fun. Let us do it again. After a nap.', 'All fixed up. Good as new. Better than new, even.', 'My Cure spam paid off. As always. You are welcome.', 'Quiet now. Just me, my staff, and total victory.', 'I healed through that whole thing. Barely broke a sweat.', 'Everyone is fine. That is my whole job description.', 'Another fight won. My halo is still shiny.', 'Time to relax. My mana is doing the same.', 'That {mob} never stood a chance. Neither will the next.', 'Perfect healing, zero deaths. I am very good at this.', 'Let us rest. I earned it. You earned it too. Fine.', 'My staff is warm, my team is alive, all is well.', 'Another victory for the healer. Shocking, I know.', 'I patch, I heal, I win. That is the routine.', 'Fight done. Time for a well earned breather.', 'Everyone alive and smiling. Mostly smiling. Good enough.', 'My holy light did great. So did I. Mostly me.', 'Rest a moment. The next {mob} can wait its turn.', 'That was textbook healing. I wrote the textbook.', 'All good. No one died. I am taking full credit.', 'I love a quiet moment after a loud victory.', 'Mana low, spirits high. Classic healer life.', 'Another {mob} handled. My record stays perfect.', 'Time to breathe. Healing is hard work, you know.', 'Victory tastes sweet. Almost as sweet as a full Cure.', 'Everyone is up. That is what I call a good day.', 'I did my job. The job was everything. You are welcome.', 'Rest now. I will keep watch. I always do.' },
            low = { 'My HP is low. My attitude is still excellent.', 'Half health, full confidence. That is the healer way.', 'I am hurt, but I am still the one healing you.', 'Low HP is just my dramatic phase. Watch this.', 'I lost some HP. I kept my dignity. Mostly.', 'Half health means half the worry. I am fine.', 'My HP dipped. My holy light did not. Stay calm.', 'I am at half health and still the scariest one here.', 'Low HP, high hopes. That is my whole brand.', 'I can heal myself, you know. I am just busy.', 'Half health is my cue to shine brighter. Watch.', 'My HP is low but my Cure is loaded and ready.', 'I am bleeding a little. I am also winning a little.', 'Do not panic. I have survived worse. Probably.', 'Half health, zero fear. I am a White Mage.', 'My HP bar is low. My spirit bar is full.', 'I took a hit. Now I take a bow. Then I heal.', 'Low HP is temporary. My awesomeness is permanent.', 'I am hurt. I am also hilarious. Priorities, people.', 'Half health means I am just getting started.', 'My HP is dropping. My jokes are not. Stay tuned.', 'I am at half health and still cracking jokes. Respect.', 'A little damage never stopped a healer. Ever.', 'My HP is low. My holy light is fully charged.', 'I am wounded, witty, and still winning. In that order.', 'Half health is just a plot twist. I love plot twists.', 'I lost HP. I gained a great story. Fair trade.', 'My HP is low. My Cure is ready. Coincidence? No.', 'I am hurt but healed. It is a complicated lifestyle.', 'Low HP, loud mouth, holy staff. That is me.', 'My health is half gone. My humor is fully intact.', 'I took a beating and I am still standing. Impressive.', 'Half health, full sass. That is the healer package.', 'My HP is low. My will to win is not.', 'I am damaged but delightful. That counts for something.', 'Low HP is my warm-up. The comeback starts now.', 'My HP bar is sad. My attitude is not. Keep going.', 'I am at half health and already planning my victory.', 'A healer at half HP is still