            critical = { 'Critical HP. Dying is not on my schedule today.', 'I am nearly dead and still the funniest one here.', 'Almost out of HP. Almost out of patience too.', 'Critical health, maximum sass. That is my final form.', 'I am hanging by a thread. A very holy thread.', 'My HP is tiny. My will to live is huge.', 'Nearly dead is still alive. I will take it.', 'Critical HP means I am officially dramatic now.', 'I am one hit from doom and still making jokes.', 'My HP is low enough to see the light. My own light.', 'Almost dead, still healing, still hilarious. Respect.', 'Critical HP. My Cure is my best friend right now.', 'I am nearly gone but my holy light is still on.', 'One more hit and I am a legend. A living legend, please.', 'My HP is critical. My comedy timing is perfect.', 'I am down to my last HP and my last joke. Both great.', 'Nearly dead is my favorite plot twist. Watch this.', 'Critical HP. Time for a miracle. I make those.', 'I am almost out. Almost is not out. Keep fighting.', 'My health is critical. My confidence is not.', 'I am barely alive and still the team MVP.', 'Critical HP, holy heart, zero plans to die.', 'I am on my last legs and my best jokes. Enjoy.', 'Almost dead means almost a great story. Stay with me.', 'My HP is nearly gone. My spirit is nowhere near gone.', 'Critical health is just healing with extra drama.', 'I am one Cure away from a full comeback. Watch.', 'Nearly dead, still standing, still sassy. That is me.', 'My HP is critical. My holy light is furious.', 'I am almost a ghost. A very funny ghost. Not yet though.', 'Critical HP. I refuse to die before the punchline.', 'My health is tiny. My talent is enormous. Balance.', 'I am hanging on by holy light and pure stubbornness.', 'Almost dead is still alive. I call that winning.', 'My HP is critical. My jokes are critically good too.', 'I am nearly out of health and out of patience. Heal me.', 'Critical HP means the comeback starts right now.', 'I am down bad and still cracking wise. Classic me.', 'My HP is almost zero. My awesomeness is not.', 'I am nearly dead. I am also nearly legendary. Same thing.' },
            recover = { 'Back on my feet. The miracle worker returns.', 'Healed up and ready to shine again. Watch this.', 'HP restored. My halo is polished and glowing.', 'I am back. Did you miss me? Of course you did.', 'Recovered and radiant. That is my natural state.', 'Full health again. The healer heals herself too.', 'I am patched up and feeling fantastic. Let us go.', 'Back to full HP. The comeback is complete.', 'My HP is back. My jokes never left. Enjoy.', 'Recovered, recharged, and ready to smite something.', 'I am healthy again. The team can relax now.', 'Back in action. My Cure did its magic. Again.', 'HP restored, spirits restored, sass restored. All good.', 'I feel great. Healing works. Who knew? I did.', 'Back to full strength. I was never really down.', 'Recovered and glowing. Holy light looks good on me.', 'My HP is back up. My confidence never dropped.', 'I am healed, whole, and hilariously ready to fight.', 'Full HP again. That was a quick miracle. I am fast.', 'Back on track. The healer is healed. All is well.', 'Recovered and radiant. Let us find the next {mob}.', 'I am up again. Death can wait. It always does.', 'HP full, mana full, ego full. Perfect balance.', 'I patched myself up. I am very good at my job.', 'Back to life, back to reality, back to winning.', 'Recovered completely. My holy light never quits.', 'I am healthy, happy, and hilariously heroic again.', 'Full health restored. Time to return the favor.', 'I am back at full HP. The danger has passed. Probably.', 'Recovered and ready. The next {mob} is in trouble.', 'My HP is back. My staff is ready. Let us move.', 'Healed up, head high, halo shining. Classic me.', 'I am whole again. Miracles happen. I make them.', 'Back to full power. The team is safe with me.', 'Recovered nicely. I do love a good comeback story.', 'HP restored. My jokes are also fully restored.', 'I am back and better than ever. Watch me shine.', 'Full health, full heart, full holy power. Let us go.', 'I healed myself. I am my own favorite patient.', 'Recovered and radiant. The healer is here to stay.' },
            ko = { 'You died. Do not worry. I am a professional at this.', 'Down you go. I will patch you up. Again. As usual.', 'You are dead. I am not. That is why I am the healer.', 'Another death, another Cure. I have seen worse. Maybe.', 'You fell. I am still standing. Somebody has to heal you.', 'Dead again? Fine. I will fix it. I always do.', 'You died heroically. I will revive you practically.', 'Down and out. My Cure is already on its way.', 'You are on the floor. I am on the job. Hold still.', 'Death is temporary. My healing is permanent. Relax.', 'You died. I am shocked. Shocked and already healing.', 'Another KO. Another reason I am the team MVP.', 'You fell down. I will pick you up. With magic.', 'Dead is just a status effect. I remove those for a living.', 'You are dead. I am the reason that will not last long.', 'Down you go. Up you go. That is the healer cycle.', 'You died. My Cure was this close. Next time, duck.', 'A KO is just a nap with extra drama. Wake up soon.', 'You are down. I am still here. That is the whole plan.', 'Death called. I told it to wait. You are coming back.', 'You fell. I caught you. With holy light. You are welcome.', 'Another death. My revive count keeps climbing. Impressive.', 'You are dead, but my holy light is not done with you.', 'Down again. I will fix you. I am very good at fixing.', 'You died. I am already casting. That is how this works.', 'A KO is no match for a White Mage with a plan.', 'You are on the ground. My Cure is in the air. Hold on.', 'Dead today, alive in a moment. That is my promise.', 'You fell hard. I heal harder. Get ready to stand up.', 'Another KO, another miracle. I should charge extra.', 'You are dead. My staff disagrees. Watch this.', 'Down you go. My holy light says not today, friend.', 'You died. I am not even surprised. I am prepared.', 'A KO is just a timeout. I am the coach. Get up.', 'You are down. My Cure is up. The math works out.', 'Death is a door. I have the key. It is called Cure.', 'You fell. I will raise you. That is literally my job.', 'Another death, another day at the office for me.', 'You are dead. Relax. I do this all the time.', 'Down but not out. My healing says you are coming back.' },
