    SAM = {
        middles = {
            engage = { 'That {mob} picked a fight with a blade master.', 'One clean cut. That is the whole plan.', 'My katana has been waiting all day for this.', 'Honor says hello. My blade says goodbye.', 'I drew my sword. The {mob} drew the short straw.', 'Let us see if that {mob} can dodge honor.', 'My blade is sharp. My wit is sharper. Sorry.', 'Time to turn that {mob} into a lesson.', 'I do not miss. I just cut twice on purpose.', 'The way of the sword starts with one step.', 'That {mob} looks like practice. Lucky me.', 'Meditate first, then mayhem. That is the order.', 'My katana does the talking. I just translate.', 'One swing opens a skillchain. Art in motion.', 'That {mob} chose violence. I chose precision.', 'I bow to no {mob}. I bow, then I cut.', 'Steel out, worries out. Let us dance.', 'The {mob} is brave. Brave and doomed.', 'My edge is honed. My timing is better.', 'A samurai never rushes. He just arrives on time.', 'That {mob} is about to learn what sharp means.', 'I keep my blade clean and my jokes cleaner.', 'One cut solves most problems. This is one.', 'The {mob} growled. My katana laughed.', 'Precision beats power. Watch and learn.', 'I am calm, collected, and slightly dangerous.', 'That {mob} interrupted my meditation. Rude.', 'My sword is drawn. The outcome is drawn too.', 'Honor, steel, and one very unlucky {mob}.', 'I aim for the perfect cut. Every single time.', 'That bat is about to meet my katana.', 'Another bat, another perfect cut. Easy.', 'Let us make this quick, clean, and quotable.', 'I do not chase glory. Glory chases my blade.', 'That {mob} has no idea what is coming.', 'My stance is perfect. My puns are close.', 'A single cut, delivered with great ceremony.', 'The {mob} picked the wrong samurai today.', 'I fight with honor and a dash of showmanship.', 'Steel cuts. I joke. The {mob} falls. Simple.' },
            idle = { 'Sheathing my blade. Another duel done right.', 'My katana is clean. My conscience is cleaner.', 'That was a fine cut. I shall remember it fondly.', 'Resting now. Even legends need a breather.', 'My blade rests. My honor stays on duty.', 'A samurai rests with style. Watch me rest.', 'The dust settles. I am still standing. Obviously.', 'I polish my katana while the world catches up.', 'Victory tastes better after a perfect cut.', 'I am not tired. I am dramatically paused.', 'My katana rests. My honor stays sharp.', 'That fight was short. My cut was shorter.', 'I meditate between duels. It is called pacing.', 'The {mob} is gone. My blade work remains.', 'I take a bow. The audience is mostly me.', 'Rest now, blade. You earned the quiet.', 'A clean cut deserves a clean rest after.', 'My stance relaxes. My reputation does not.', 'I stand here, victorious and slightly smug.', 'The field is quiet. My katana is quieter.', 'I could fight all day. I choose to rest instead.', 'Honor intact, blade intact, ego mostly intact.', 'That was exercise. Real duels come later.', 'I sheath my sword like closing a good book.', 'My breathing is calm. My blade is calmer.', 'Another victory filed under routine.', 'I rest my feet. My blade never truly rests.', 'The sun sets, the bat falls, I remain.', 'My katana gleams with satisfaction. Totally normal.', 'I did not even break a sweat. I checked twice.', 'A samurai naps with one eye on the horizon.', 'That duel is done. Next challenger, please.', 'I look calm because I am calm. Mostly.', 'My blade is sheathed, but my timing is ready.', 'Victory suits me. It always has.', 'I rest now so the next cut is perfect.', 'The {mob} gave its best. Its best was short.', 'I call that a warmup. A very short warmup.', 'My honor is polished. My katana is too.', 'Standing here, looking heroic, as required.' },
            low = { 'My HP is low. My blade is still full.', 'Half my health is gone. My honor is intact.', 'I am bleeding a little. My jokes are not.', 'The {mob} got lucky. Luck runs out fast.', 'Low HP, high standards. That is the deal.', 'I fight better with a little danger involved.', 'My health bar is short. My sword is long.', 'This is fine. A samurai never panics. Mostly.', 'The {mob} thinks it is winning. Adorable.', 'I am down to half. The {mob} is down to luck.', 'A scratch like this never stopped a legend.', 'My blade does not care about my HP bar.', 'I have been lower. I have also been funnier.', 'Half health, full honor, zero fear. Mostly.', 'The {mob} cut me. I shall return the favor.', 'I call this a dramatic midpoint. Stay tuned.', 'My wounds are minor. My timing is major.', 'Low health just means the comeback starts now.', 'I am hurt, not beaten. There is a difference.', 'The {mob} drew first blood. I draw last.', 'My HP is dropping. My standards are not.', 'A samurai fights on. Bandages come later.', 'This {mob} fights dirty. I fight precisely.', 'I am at half strength and still twice as sharp.', 'My health is low. My katana disagrees loudly.', 'The {mob} should enjoy this while it lasts.', 'I have survived worse. Ask my last {mob}.', 'Half my HP left, all of my nerve left.', 'This is the part where I look heroic and hurt.', 'My blade is steady even when my knees wobble.', 'Low HP is just a plot twist with a sword.', 'The {mob} hit me. Rude. Unforgivable. Fixable.', 'I am wounded, witty, and still winning. Probably.', 'My honor does not leak out with my HP.', 'I keep fighting. Retreat is not in my stance.', 'The {mob} got a hit in. It will not get two.', 'My health bar is shy. My blade is bold.', 'I fight on one good leg and a great katana.', 'This {mob} picked a bad day to be brave.', 'A little blood, a lot of blade. Fair trade.' },
            critical = { 'I am nearly done, but my blade is not.', 'Critical HP. My jokes are now my armor.', 'The {mob} almost has me. Almost is the key word.', 'I am one cut from glory or a dirt nap.', 'My health is a rumor. My katana is a fact.', 'This is fine. I have survived closer calls.', 'The {mob} smells victory. It smells wrong.', 'I am running on honor and stubbornness now.', 'One more hit and I am a cautionary tale.', 'My HP is tiny. My nerve is enormous.', 'I refuse to fall before my punchline lands.', 'The {mob} is winning the numbers, not the duel.', 'I refuse to fall. My katana has other plans.', 'Critical health, critical wit, critical blade.', 'My knees are weak. My grip is not.', 'This {mob} will have to earn this kill. Hard.', 'I am hanging on by a thread and a katana.', 'Death can wait. I have a cut to finish.', 'My health bar is blinking. My blade is shining.', 'I have been closer to death than this. Probably.', 'The {mob} thinks I am done. Classic mistake.', 'I am not dying. I am just fighting dramatically.', 'One clean cut could still turn this around.', 'My HP is low enough to make this legendary.', 'I fight on fumes and flawless footwork.', 'The {mob} has me cornered. I like corners.', 'If I fall, I fall with style and a quip.', 'My blade is the last thing this {mob} sees.', 'I am at the door of death, knocking politely.', 'Critical is just another word for interesting.', 'My heart is pounding. My aim is steady.', 'The {mob} wants a win. I want a story.', 'I am nearly out, but my honor is fully charged.', 'This is where heroes either shine or nap forever.', 'My wounds are many. My regrets are zero.', 'I will not die to a {mob} with no manners.', 'The {mob} is strong. My stubbornness is stronger.', 'I have one good cut left. It will count.', 'Dying now would ruin my perfect record. Nope.', 'My HP is a whisper. My blade is a shout.' },
            recover = { 'Back on my feet. The blade never left my hand.', 'Health restored. Honor never left. Let us go.', 'I am back. The {mob} should be worried again.', 'That was a nap, not a defeat. I am fine.', 'My HP is back. My swagger is back too.', 'Patched up, sharpened up, ready to cut up.', 'I feel stronger. The katana agrees with me.', 'Recovery complete. The legend resumes now.', 'My wounds closed. My confidence never did.', 'Back above half. The comeback tour begins.', 'I am healed, honed, and hungry for the next cut.', 'The {mob} missed its chance. Shame for it.', 'Good as new. Better, actually. I learned things.', 'My health is back and so is my timing.', 'I stood up. That is the whole trick, really.', 'Fresh HP, fresh edge, same old brilliance.', 'The danger passed. My blade stayed sharp.', 'I am recovered and ready to be brilliant again.', 'My knees stopped wobbling. My blade never did.', 'Back in form. The {mob} had its moment.', 'Health up, spirits up, katana up. Let us go.', 'I took a hit and took notes. Notes help.', 'That was a close call. I call it a warmup now.', 'My HP bar is green and my blade is gleaming.', 'Recovered, rebalanced, and ready to duel again.', 'The {mob} thought it had me. It had a minute.', 'I am back to full swagger and full steel.', 'My wounds healed faster than my ego did.', 'A samurai rises. It is what we do best.', 'Health restored, honor intact, jokes reloaded.', 'I am on my feet and my blade is in my hand.', 'The comeback starts with one clean cut.', 'My HP is healthy. My wit is healthier.', 'I shook it off like dust from my shoulders.', 'Back from the edge, blade first as always.', 'The {mob} blinked and I am back already.', 'I heal fast. My katana heals faster. Somehow.', 'My strength returns. So does my showmanship.', 'That breather worked wonders. Watch this cut.', 'I am whole again. The duel continues now.' },
            ko = { 'I died with my boots on and my blade out.', 'Well, that {mob} got lucky. Very lucky.', 'I fell, but my honor stayed standing. Mostly.', 'Death took me down. My katana objects loudly.', 'That was not a defeat. That was a dramatic exit.', 'I am down. Somebody avenge my perfect hair.', 'The {mob} won this round. I want a rematch.', 'I died as I lived: overconfident and stylish.', 'My blade is on the ground. My pride is not.', 'Tell the {mob} I shall be back. Sharper.', 'I took a dirt nap with full ceremony.', 'Death is just a long meditation. I am back soon.', 'I fell with honor. Mostly honor. Some style.', 'I fell to a {mob}. History will forget the details.', 'That {mob} cheated. I am sure of it. Mostly.', 'I am down, not out. A samurai always rises.', 'My katana and I took a short break. On the floor.', 'I died bravely. Bravely and a little clumsily.', 'The {mob} got me. I got a great story.', 'I am flat on my back and still funnier than that {mob}.', 'Death, you may wait. I have cuts to finish.', 'I went down swinging. Literally. Ask the {mob}.', 'My soul is fine. My body needs a minute.', 'That was a tactical nap. A very flat one.', 'I am deceased, not defeated. There is a difference.', 'The {mob} beat me. I demand a recount.', 'I died with honor and a halfway decent quip.', 'Somebody pick up my katana. It hates the dirt.', 'I fell hard. My legend fell softer. Somehow.', 'That {mob} will regret this when I stand up.', 'I am out cold and still the coolest one here.', 'Death came calling. I answered with a bow.', 'My final cut was almost perfect. Almost.', 'I am down. The {mob} is still ugly, though.', 'A samurai falls forward, never back. Mostly.', 'I need a raise and a rematch, in that order.', 'That was embarrassing. Let us never speak of it.', 'I died, but my blade stayed sharp. Priorities.', 'The {mob} won. Enjoy it. It will not last.', 'I shall return, katana first, jokes second.' },
