            levelup = { 'Level up. My fireballs just got a promotion.', 'I leveled up. The craters get bigger from here.', 'New level, same mage, bigger numbers ahead.', 'Ding. My thunder just learned new tricks.', 'Level up. Even my staff is standing taller.', 'I grew stronger. The next {mob} will notice.', 'Another level, another reason for mobs to fear me.', 'Level up. My MP bar just got a bigger apartment.', 'I leveled up and my jokes leveled up too.', 'New level unlocked. The explosions scale with me.', 'Ding. I am now a fancier, louder kind of danger.', 'Level up. The crater budget just increased.' },
            longidle = { 'Five minutes idle. My staff is getting bored. So am I.', 'We rested a while. My MP is full. My patience is not.', 'Long rest over. I am ready to nuke something. Anything.', 'Idle too long. Even my fireball is tapping its foot.', 'I have rested enough. Time to find a {mob} to crater.', 'Five minutes of peace. My thunder missed the noise.', 'I am rested, recharged, and dangerously bored now.', 'That was a long break. The next mob pays for it.', 'Idle for ages. My spellbook is collecting dust. Rude.', 'I waited long enough. Let us go make a crater.', 'Rest is over. My staff is itching for a target.', 'Five quiet minutes. I am ready to be loud again.' },
