    THF = {
        middles = {
            engage = { 'That {mob} never saw the dagger coming.', 'Your loot is mine. Your HP is next.', 'I am behind you. That is the whole plan.', 'Sneak Attack says hello. From behind.', 'Treasure Hunter is not a hobby. It is a lifestyle.', 'I took your wallet and your confidence.', 'Fast hands. Faster dagger. Fastest exit.', 'That {mob} blinked and lost everything.', 'I do not fight fair. I fight first.', 'I checked your pockets. Nothing worth keeping.', 'The dagger is small. The crit is not.', 'You never saw me. You will feel me.', 'I am the reason locks were invented.', 'That {mob} has loot. I have a plan.', 'Stealth is my armor. Speed is my shield.', 'I strike from behind because fronts are rude.', 'Your gold called me. I answered.', 'One dagger, two pockets, zero mercy.', 'I am quicker than your eyes. Ask your HP.', 'That {mob} is about to fund my retirement.', 'Sneak Attack charged. Manners optional.', 'I hide in plain sight. Then I stab.', 'Your treasure was mine before we met.', 'Daggers are quiet. So am I. Mostly.', 'That {mob} picked the wrong pocket to guard.', 'I am not late. I am fashionably behind you.', 'Every lock opens. Every mob drops loot.', 'The bat never saw it coming. Neither will you.', 'I move fast. Your loot moves faster. Into my bag.', 'Behind every great thief is a surprised {mob}.', 'I did not sneak up. You just noticed late.', 'Your HP bar is my shopping list.', 'Treasure Hunter level: yes.', 'I am the shadow with a dagger and a grin.', 'That {mob} is rich in loot and poor in luck.', 'Quick feet, quick hands, quicker dagger.', 'I steal the show and the loot. Mostly the loot.', 'No alarms. No witnesses. Just a dagger.', 'That {mob} never stood a chance. Or a guard.', 'Bats beware. I am the thing in the dark.' },
            idle = { 'Another {mob} down. Another pocket lighter.', 'Resting now. Counting loot is hard work.', 'The dagger rests. The grin does not.', 'I looted the {mob}. It looted nothing back.', 'Idle hands are a thief playground.', 'That fight was easy. The loot was easier.', 'I am rich in loot and poor in patience.', 'Another victory. Another full bag.', 'The {mob} is down. My pockets are up.', 'Resting is just plotting with snacks.', 'I never miss. I just reload my swagger.', 'The loot is counted. The legend grows.', 'That {mob} paid for my next adventure.', 'Quiet now. The dagger is napping.', 'I took everything. Even the good vibes.', 'Another mob, another payday. I love this job.', 'My dagger is clean. My conscience is flexible.', 'The {mob} never knew what hit it. Classic.', 'Rest time. Treasure Hunter never sleeps.', 'I am not tired. I am strategically still.', 'That was fast. I am faster.', 'Loot secured. Dignity optional. Swagger kept.', 'The shadows missed me. I was busy winning.', 'Another {mob} bites the dust. I take the dust too.', 'I rest like I fight: quickly and stylishly.', 'The bag is full. The grin is fuller.', 'That {mob} had great loot and terrible luck.', 'I am the fastest rest in the west. And east.', 'Victory tastes like gold. I checked.', 'The dagger is sheathed. The wit is not.', 'I did not break a sweat. I broke a lock.', 'That fight is over. The loot lives on.', 'Resting now, plotting later, looting always.', 'The {mob} is history. I am the future.', 'I am so smooth the shadows take notes.', 'Another win. My pockets send their thanks.', 'The mob is down. The myth grows.', 'I loot first and ask questions never.', 'That was a warmup. The loot was real.', 'Bats down, loot up. Business as usual.' },
            low = { 'My HP is low. My swagger is not.', 'Half HP, full attitude. Let us go.', 'I am hurt, not finished. Big difference.', 'Low HP is just a dramatic pause.', 'The {mob} got lucky. Once. Never again.', 'I bleed gold, not fear. Mostly gold.', 'Half health, double the cunning.', 'I am down to half. The {mob} is down to nothing.', 'Wounded thief, dangerous thief. Ask the {mob}.', 'HP at half. Dagger at full. Math checks out.', 'I have been lower. I have also been richer.', 'The {mob} thinks it is winning. Cute.', 'Low HP, high hopes, sharp dagger.', 'I am not scared. I am strategically bleeding.', 'Half HP means half the mercy. Zero, actually.', 'The dagger still works. So do I.', 'I took a hit. I will take your loot too.', 'My HP bar is low. My luck bar is not.', 'Wounded but witty. That counts as armor.', 'The {mob} hit me. Rude. Expensive mistake.', 'I am at half health and full mischief.', 'Low HP is a plot twist, not an ending.', 'The thief is hurt. The thief is also angry.', 'I can take a hit. I prefer taking loot.', 'Half HP, all attitude, one sharp dagger.', 'The {mob} got one in. It will regret it.', 'I am bleeding, bantering, and still winning.', 'Low health, high speed, zero surrender.', 'My HP dropped. My standards did not.', 'The dagger is hungry. The {mob} is next.', 'I am hurt and hilarious. A dangerous combo.', 'Half HP is plenty for a thief this fast.', 'The {mob} landed a hit. I landed a plan.', 'Wounded is just another word for motivated.', 'I am low on HP and high on revenge.', 'The hit hurt. The comeback will hurt more.', 'My health is half. My nerve is whole.', 'Low HP, quick feet, quicker payback.', 'The {mob} should enjoy its loot while it lasts.', 'Bats bite hard. I bite back harder.' },
            critical = { 'Critical HP. Comedy levels still maximum.', 'I am nearly dead. I am also nearly rich.', 'One hit from done. One hit from legend.', 'The {mob} almost got me. Almost is not got.', 'Critical health, critical wit, critical dagger.', 'I am hanging by a thread and a punchline.', 'Nearly dead is still alive. Ask the loot.', 'My HP is a rumor now. My dagger is real.', 'This is fine. I have survived worse. Probably.', 'Critical HP means the getaway starts now.', 'The {mob} thinks I am done. Watch this.', 'I am one dagger away from a miracle.', 'Almost dead, fully dangerous, totally unbothered.', 'My health bar is tiny. My nerve is huge.', 'I refuse to die before I loot the {mob}.', 'Critical is just dramatic. I do drama well.', 'The thief is down to a sliver. Still smiling.', 'I have dodged worse. I have dodged taxes.', 'One more hit and I am a legend. Or a ghost.', 'The {mob} wants me dead. I want its loot.', 'Critical HP, maximum swagger, zero fear.', 'I am barely standing. I am fully scheming.', 'This close to death and still cracking jokes.', 'My HP is low enough to see the light. I winked.', 'The dagger is my lifeline. The wit is my shield.', 'Nearly gone, never giving up, always looting.', 'I am at death door and I am picking its lock.', 'Critical health is just a plot twist I wrote.', 'The {mob} is close. So is my comeback.', 'I am fragile, fast, and furious. Mostly fast.', 'Death can wait. The loot cannot.', 'My HP bar blinked. I blinked back.', 'I am one crit away from turning this around.', 'The thief is critical. The jokes are not.', 'Almost dead means almost a great story.', 'I am hanging on by wit and a dagger.', 'The {mob} almost wins. Almost is my favorite word.', 'Critical HP. The punchlines write themselves.', 'I am not dying. I am dramatically waiting.', 'Bats nearly got me. Bats will regret it.' },
            recover = { 'Back from the brink and still grinning.', 'HP is back. So is the attitude.', 'I am healed up and ready to rob again.', 'That was close. The loot is closer.', 'Recovered, reloaded, and ready to steal.', 'My HP is back. Your loot is next.', 'I survived. The {mob} should be worried.', 'Back on my feet. Back in your pockets.', 'Healing done. Scheming resumed.', 'I am whole again. The plan is whole too.', 'That scare was free. The loot is not.', 'HP restored. Swagger never left.', 'I am back and better at stealing than ever.', 'The danger passed. The dagger stayed.', 'Recovered and richer in spirit. And soon in loot.', 'My health is up. My ambitions are higher.', 'I dodged death and kept the loot. Classic thief.', 'Back to full HP and full mischief.', 'The {mob} missed its chance. I never miss mine.', 'Healed, hidden, and hungry for loot.', 'I am patched up and plotting already.', 'That was a close call. The next one is yours.', 'HP back up. Confidence never dropped.', 'I survived the worst. Now for the loot.', 'Recovered fast. Thieves always do.', 'My HP is green again. My plans are gold.', 'Back in action. The {mob} is back on the menu.', 'I am healed. The dagger is thirsty.', 'That was dramatic. I do drama well.', 'Full health, full pockets soon, full speed ahead.', 'The scare is over. The stealing resumes.', 'I am back on my feet and in your pockets.', 'HP restored. The legend continues.', 'I survived and I am still funny. Amazing.', 'The {mob} failed. I prevailed. Loot time.', 'Recovered, regrouped, and ready to rob.', 'My health returned. So did my nerve.', 'I am whole, witty, and wonderfully fast.', 'That was nothing. The loot is everything.', 'Bats could not finish me. Nobody can.' },
            ko = { 'I died? The loot is still mine. I call dibs.', 'Death took me. It did not take my loot.', 'I am down, not out. Thieves always return.', 'The {mob} got me this time. This time only.', 'I died with style. And full pockets.', 'Death is just a really long hide.', 'I am dead. The dagger is still sharp.', 'The {mob} won the round. I win the war.', 'Down I go. Up I come. Thieves bounce.', 'I died? Rude. I was mid-scheme.', 'Death caught the thief. It cannot keep me.', 'I am flat on the ground, plotting my return.', 'The {mob} got lucky. I get revenge.', 'I died dramatically. It was a great scene.', 'Down but not defeated. Loot waits for no one.', 'Death is a locked door. I pick locks.', 'I am KOed. The loot is still calling.', 'The {mob} beat me. I beat the odds before.', 'I died with a grin. The grin stays.', 'Death took a thief. It got more than it bargained.', 'I am down. My swagger is still standing.', 'The floor is comfy. The revenge will be better.', 'I died? Fine. I will steal death itself next.', 'The {mob} wins this round. I take the next.', 'Down I am, out I am not. Watch me return.', 'I got KOed. The loot got away. For now.', 'Death is just another pocket to pick.', 'I am dead and still the funniest one here.', 'The {mob} got me. I got its loot first.', 'I died stylishly. Style points count double.', 'Flat on my back, rich in plans.', 'The thief is down. The legend is not.', 'I died? The shadows will miss me. Briefly.', 'Death is a detour, not a destination.', 'I am out cold. My wit is still warm.', 'The {mob} won. I am already planning round two.', 'I died with my boots on. And loot in them.', 'Down goes the thief. Up goes the comeback.', 'I am dead. The joke is not over.', 'Bats got me. Bats will pay for it.' },
