        middles = {
            engage = { 'That {mob} is about to meet my favorite rune.', 'I have a rune for that {mob}. Several, actually.', 'Sword in one hand, runes in the other. Let us go.', 'I carved a rune for this {mob}. It says trouble.', 'Time to tank magic with a sword and a smile.', 'That {mob} picked a fight with a walking ward.', 'Ignis rune lit. That {mob} is about to feel it.', 'I am the magic tank. The magic part is literal.', 'My sword has runes. My runes have opinions.', 'That {mob} is standing in my rune circle.', 'I brought a sword to a spell fight. I win anyway.', 'Wards up, sword out, {mob} in trouble.', 'That {mob} is about to learn what a rune does.', 'I carve runes mid-fight. Multitasking is my job.', 'Elemental resistance is my love language, {mob}.', 'That bat flew into the wrong rune circle.', 'Vallation is up. That {mob} can try its worst.', 'My runes glow. That {mob} should run now.', 'I tank spells. Swords are just for decoration.', 'That {mob} is one ward away from a bad day.', 'Swordplay ready. Runes ready. {mob} ready? No.', 'I etched a rune on my sword. It says {mob} loses.', 'That {mob} is warded against and out of luck.', 'My blade is rune-etched. My attitude is too.', 'I do not dodge spells. I collect them in runes.', 'That {mob} chose the tank with a magic sword.', 'Runes first, questions later, {mob}.', 'I am a wall made of wards and sharp edges.', 'That {mob} is about to get runed and ruined.', 'Pflug is up. That {mob} can hit me all day.', 'I brought eight runes. That {mob} gets all eight.', 'My sword channels elements. That {mob} channels fear.', 'That {mob} is the reason I carry a rune pouch.', 'Wards humming, sword singing, {mob} doomed.', 'I tank with runes, I hit with a sword, I win.', 'That bat is about to meet my lightning rune.', 'Elemental tank reporting for duty, {mob}.', 'My runes are carved. That {mob} is carved next.', 'I am not a mage. I am a tank with homework.', 'That {mob} is standing where my runes say no.' },
            idle = { 'Fight over. My runes are still glowing, though.', 'I rest now. My wards earned a coffee break.', 'That {mob} is gone. My sword is still humming.', 'Another victory, courtesy of runes and good timing.', 'I sit down. Carving runes is tiring work, you know.', 'The wards fade. The tank remains fabulous.', 'I rest, I recharge, I redraw my runes.', 'Quiet at last. Even my sword is catching breath.', 'That fight is over. My rune pouch stays open.', 'I am resting my runes, not my sense of humor.', 'Another mob down. I barely broke a rune. Or a nail.', 'I rest now so the next mob can fear my runes.', 'My sword is cooling down. So am I. Barely.', 'That was fun. My wards disagree, but that was fun.', 'I am out of enemies and low on runes. Perfect timing.', 'Resting now. The next mob can wait for my runes.', 'That {mob} is history. I am the rune carver.', 'I take a bow. The wards take the applause.', 'Peace and quiet, plus one glowing rune circle.', 'I meditate. My runes meditate harder.', 'That fight ended with a ward. Literally. Several.', 'I am resting. Do not poke the tank. Seriously.', 'The wards fade. My legend grows. Both are normal.', 'I sit, I carve nothing, I recharge everything.', 'My rune pouch is lighter. My legend is heavier.', 'I rest my feet. My wards never rest for long.', 'That bat is toasted. I am taking a breather.', 'I am calm, collected, and slightly rune-scorched.', 'No mobs, no problem, just me and my sword.', 'I recharge in style. Runes are my middle name.', 'That was a warm-up. The real wards come later.', 'My sword hums with leftover lightning. Nice.', 'Sitting is underrated. Warding things is not.', 'I am recharging. The runes are recharging too.', 'That rune circle will be a landmark someday. Mine.', 'I take five. My wards take fifty. They are dramatic.', 'Resting is just re-carving with extra steps.', 'The fight is done. My runes are just warming up.', 'My blade is sheathed. My runes are still on duty.', 'I earned this rest. I